  ? "Yes: " + $working + " working days cover the " + slots.noticeDays + " the extract requires."
  : "No: " + slots.noticeDays + " working days > " + slots.announceDay + "-" + slots.leaveDay + ".";
return paidClause + " " + leaveClause;

